#include "guidance_horizontal.h"
static uint8_t valid(const p66_preparation *s,const p66_pushdown *p,agc_word mode,uint8_t offset){return (uint8_t)(s->mpac[7]==mode&&p->base>=0401&&p->base<=0661&&(uint16_t)(p->base-0401u)%054u==0&&p->pushloc==p->base+offset);}
enum p66_horizontal_status p66_horizontal_load(p66_preparation *s,p66_norm_scratch *n,p66_pushdown *p){static const uint8_t at[3]={0,3,5};agc_word old_lo;uint8_t i;if(!valid(s,p,0,0))return P66_HORIZONTAL_OUT_OF_SCOPE;old_lo=s->mpac[6];for(i=0;i<3u;++i){s->mpac[at[i]]=p->words[24u+2u*i];s->mpac[at[i]+1u]=p->words[25u+2u*i];}s->mpac[7]=077776;s->rate.registers.a=agc_extend(077776);s->rate.registers.l=agc_extend(old_lo);n->addrwd=(agc_word)(p->base+24u);return P66_HORIZONTAL_OK;}
enum p66_horizontal_status p66_horizontal_surface(p66_preparation *s,p66_scale_scratch *sc,p66_elapsed_state *el,p66_norm_scratch *n,p66_pushdown *p,const agc_word delvs[6]){if(!valid(s,p,077776,0))return P66_HORIZONTAL_OUT_OF_SCOPE;(void)p66_vector_shift_left(s,sc,el,2,1);(void)p66_vector_add(s,sc,el,delvs);n->addrwd=031733;return P66_HORIZONTAL_OK;}
enum p66_horizontal_status p66_horizontal_position(p66_preparation *s,p66_scale_scratch *sc,p66_elapsed_state *el,p66_norm_scratch *n,p66_pushdown *p,const agc_word position[6]){static const uint8_t at[3]={0,3,5};agc_word old_hi=p->words[4],old_lo=p->words[5];uint8_t i;if(!valid(s,p,077776,0))return P66_HORIZONTAL_OUT_OF_SCOPE;(void)p66_vector_shift_right(s,sc,2,1);for(i=0;i<3u;++i){p->words[2u*i]=s->mpac[at[i]];p->words[2u*i+1u]=s->mpac[at[i]+1u];s->mpac[at[i]]=position[2u*i];s->mpac[at[i]+1u]=position[2u*i+1u];}p->pushloc=(agc_word)(p->base+6u);s->rate.registers.a=agc_extend(old_hi);s->rate.registers.l=agc_extend(old_lo);n->addrwd=01520;(void)el;return P66_HORIZONTAL_OK;}
enum p66_horizontal_status p66_horizontal_radial(p66_preparation *s,p66_scale_scratch *sc,p66_elapsed_state *el,p66_divide_scratch *d,p66_norm_scratch *n,p66_pushdown *p,const agc_dp *hdot){enum p66_unit_result result;if(!valid(s,p,077776,6))return P66_HORIZONTAL_OUT_OF_SCOPE;result=p66_unit_vector(s,sc,el,d,n,p);if(result==P66_UNIT_ALARM_1302)return P66_HORIZONTAL_ALARM_1302;(void)p66_vector_multiply(s,sc,hdot);n->addrwd=01473;return result==P66_UNIT_OVERFLOW?P66_HORIZONTAL_UNIT_OVERFLOW:P66_HORIZONTAL_OK;}
enum p66_horizontal_status p66_horizontal_tangential(p66_preparation *s,p66_scale_scratch *sc,p66_elapsed_state *el,p66_norm_scratch *n,p66_pushdown *p){agc_word operand[6];uint8_t i;if(!valid(s,p,077776,6))return P66_HORIZONTAL_OUT_OF_SCOPE;(void)p66_vector_shift_left(s,sc,el,1,1);for(i=0;i<6u;++i)operand[i]=p->words[i];p->pushloc=p->base;n->addrwd=p->base;(void)p66_vector_reverse_subtract(s,sc,el,operand);return P66_HORIZONTAL_OK;}
enum p66_horizontal_status p66_horizontal_length(p66_preparation *s,p66_scale_scratch *sc,p66_elapsed_state *el,p66_divide_scratch *d,p66_norm_scratch *n,p66_pushdown *p){enum p66_norm_result result;if(!valid(s,p,077776,0))return P66_HORIZONTAL_OUT_OF_SCOPE;result=p66_vector_length(s,sc,el,d,n,p);return result==P66_NORM_ALARM_1302?P66_HORIZONTAL_ALARM_1302:P66_HORIZONTAL_OK;}
enum p66_horizontal_status p66_horizontal_store(p66_preparation *s,p66_norm_scratch *n,p66_pushdown *p,agc_dp *vhoriz){agc_word old_lo;if(!valid(s,p,0,0))return P66_HORIZONTAL_OUT_OF_SCOPE;old_lo=vhoriz->low;vhoriz->high=s->mpac[0];vhoriz->low=s->mpac[1];s->rate.registers.a=0;s->rate.registers.l=agc_extend(old_lo);n->addrwd=01662;return P66_HORIZONTAL_OK;}
enum p66_horizontal_status p66_horizontal_exit(p66_preparation *s,p66_pushdown *p){if(!valid(s,p,0,0))return P66_HORIZONTAL_OUT_OF_SCOPE;s->rate.registers.a=agc_extend(064007);return P66_HORIZONTAL_OK;}
